export const uid=()=>globalThis.crypto.randomUUID();
export const palette=(()=>{const values=[],levels=[0,95,135,175,215,255];for(const r of levels)for(const g of levels)for(const b of levels)values.push((r<<16)|(g<<8)|b);const grays=Array.from({length:254},(_,i)=>i+1).filter(n=>!levels.includes(n));for(let i=0;i<40;i++){const v=grays[Math.floor(i*(grays.length-1)/39)];values.push((v<<16)|(v<<8)|v)}return values.map(v=>'#'+v.toString(16).padStart(6,'0'))})();
export const autoText=color=>{const value=parseInt(color.replace('#',''),16);const linear=v=>{v/=255;return v<=0.04045?v/12.92:((v+0.055)/1.055)**2.4};return .2126*linear(value>>16)+.7152*linear((value>>8)&255)+.0722*linear(value&255)>.179?'#000000':'#ffffff'};
export const defaultKeys=()=>({pause:{code:'KeyP',ctrl:true},stop:{code:'Period',ctrl:true},loop:null,talk:null});
export const initialData=()=>({version:1,pages:[{id:uid(),name:'課程音樂',cues:[]},{id:uid(),name:'活動音效',cues:[]}],settings:{width:200,height:170,keys:defaultKeys()}});
export const newCue=(name,mediaID,duration,width=200,height=170)=>({id:uid(),name,mediaID,duration,width,height,fontSize:20,color:'#454582',textColor:null,alignment:'left',start:0,end:duration,loop:false,shortcut:null});
export function validateCue(cue){if(!cue.name?.trim())return'請輸入曲目名稱';if(!Number.isFinite(cue.start)||!Number.isFinite(cue.end)||cue.start<0||cue.end>cue.duration||cue.end-cue.start<.01)return'播放區間需在曲長內，且至少 0.01 秒';if(!Number.isFinite(cue.width)||!Number.isFinite(cue.height)||cue.width<140||cue.width>600||cue.height<120||cue.height>400)return'格子寬 140–600、高 120–400';if(!Number.isFinite(cue.fontSize)||cue.fontSize<12||cue.fontSize>48)return'文字大小需為 12–48';return null}
export const keyID=k=>!k?'':[k.ctrl?'C':'',k.alt?'A':'',k.shift?'S':'',k.meta?'M':'',k.code].join(':');
export const keyLabel=k=>!k?'未設定':(k.ctrl?'Ctrl+':'')+(k.alt?'Alt+':'')+(k.shift?'Shift+':'')+(k.meta?'Win/⌘+':'')+k.code.replace(/^Key|^Digit/,'');
export function keyConflict(data,key,exclude={}){if(!key)return null;if(key.meta||(key.alt&&key.code==='F4')||(key.ctrl&&['KeyA','KeyC','KeyV','KeyX','KeyZ','KeyW','KeyQ'].includes(key.code)))return'此組合保留給系統或文字編輯';for(const page of data.pages)for(const cue of page.cues)if(cue.id!==exclude.cue&&keyID(cue.shortcut)===keyID(key))return`與「${cue.name}」重複`;for(const [action,value]of Object.entries(data.settings.keys))if(action!==exclude.action&&value&&keyID(value)===keyID(key))return'與播放控制快捷鍵重複';return null}
export function pasteCue(data,clipboard,pageID,afterID=null){const page=data.pages.find(p=>p.id===pageID);if(!page||!clipboard)return null;let index=page.cues.length;if(afterID){index=page.cues.findIndex(c=>c.id===afterID);if(index<0)return null;index++}const copy=structuredClone(clipboard);copy.id=uid();copy.shortcut=null;page.cues.splice(index,0,copy);return copy}
export function moveCue(data,pageID,fromID,toID){const page=data.pages.find(p=>p.id===pageID);if(!page||fromID===toID)return false;const from=page.cues.findIndex(c=>c.id===fromID),to=page.cues.findIndex(c=>c.id===toID);if(from<0||to<0)return false;const [cue]=page.cues.splice(from,1);page.cues.splice(to,0,cue);return true}
export const formatTime=value=>{const n=Math.max(0,Math.floor(Number.isFinite(value)?value:0));return`${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`};

export function renamePage(data,id,name){const page=data.pages.find(p=>p.id===id);if(!page||!name.trim())return false;page.name=name.trim();return true}
export function movePage(data,id,targetID){if(id===targetID)return false;const from=data.pages.findIndex(p=>p.id===id),to=data.pages.findIndex(p=>p.id===targetID);if(from<0||to<0)return false;const[page]=data.pages.splice(from,1);data.pages.splice(to,0,page);return true}
